import { DynamoDBToolboxError } from '~/errors/index.js'

import type { SchemaProps, SchemaRequiredProp } from '../types/index.js'
import { checkSchemaProps } from '../utils/checkSchemaProps.js'
import type { ItemAttributes } from './types.js'

export class ItemSchema<ATTRIBUTES extends ItemAttributes = ItemAttributes> {
  type: 'item'
  attributes: ATTRIBUTES
  props: SchemaProps

  savedAttributeNames: Set<string>
  keyAttributeNames: Set<string>
  requiredAttributeNames: Record<SchemaRequiredProp, Set<string>>

  constructor(attributes: ATTRIBUTES) {
    this.type = 'item'
    this.attributes = attributes
    this.props = {}

    this.savedAttributeNames = new Set<string>()
    this.keyAttributeNames = new Set<string>()
    this.requiredAttributeNames = {
      always: new Set(),
      atLeastOnce: new Set(),
      never: new Set()
    }

    for (const [attributeName, attribute] of Object.entries(attributes)) {
      const { key = false, required = 'atLeastOnce', savedAs = attributeName } = attribute.props

      this.savedAttributeNames.add(savedAs)
      if (key) {
        this.keyAttributeNames.add(attributeName)
      }
      this.requiredAttributeNames[required].add(attributeName)
    }
  }

  get checked(): boolean {
    return Object.isFrozen(this.props)
  }

  check(path?: string): void {
    if (this.checked) {
      return
    }

    checkSchemaProps(this.props, path)

    const attributesSavedAs = new Set<string>()
    const keyAttributeNames = new Set<string>()
    const requiredAttributeNames: Record<SchemaRequiredProp, Set<string>> = {
      always: new Set(),
      atLeastOnce: new Set(),
      never: new Set()
    }

    for (const [attributeName, attribute] of Object.entries(this.attributes)) {
      const {
        savedAs: attributeSavedAs = attributeName,
        key: attributeKey,
        required: attributeRequired = 'atLeastOnce'
      } = attribute.props

      if (attributesSavedAs.has(attributeSavedAs)) {
        throw new DynamoDBToolboxError('schema.item.duplicateSavedAs', {
          message: `Invalid item attributes${
            path !== undefined ? ` at path '${path}'` : ''
          }: More than two attributes are saved as '${attributeSavedAs}'.`,
          path,
          payload: { savedAs: attributeSavedAs }
        })
      }

      attributesSavedAs.add(attributeSavedAs)

      if (attributeKey !== undefined && attributeKey) {
        keyAttributeNames.add(attributeName)
      }

      requiredAttributeNames[attributeRequired].add(attributeName)
    }

    for (const [attributeName, attribute] of Object.entries(this.attributes)) {
      attribute.check([path, attributeName].filter(Boolean).join('.'))
    }

    Object.freeze(this.props)
    Object.freeze(this.attributes)
    Object.freeze(this.savedAttributeNames)
    Object.freeze(this.keyAttributeNames)
    Object.freeze(this.requiredAttributeNames)
  }
}

import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type { InputValue, ItemSchema, Schema, WriteMode } from '~/schema/index.js'
import { cloneDeep } from '~/utils/cloneDeep.js'
import { isFunction } from '~/utils/validation/isFunction.js'

import { anySchemaParser } from './any.js'
import { anyOfSchemaParser } from './anyOf.js'
import { listSchemaParser } from './list.js'
import { mapSchemaParser } from './map.js'
import type { InferWriteValueOptions, ParseAttrValueOptions } from './options.js'
import type { ParserReturn, ParserYield } from './parser.js'
import { primitiveSchemaParser } from './primitive.js'
import { recordSchemaParser } from './record.js'
import { setSchemaParser } from './set.js'
import { defaultParseExtension, isRequired } from './utils.js'

export function* schemaParser<OPTIONS extends ParseAttrValueOptions = {}>(
  schema: Schema,
  inputValue: unknown,
  options: OPTIONS = {} as OPTIONS
): Generator<
  ParserYield<Schema, OPTIONS>,
  ParserReturn<Schema, OPTIONS>,
  // TODO: Define & use DefaultedValue here
  InputValue<ItemSchema, InferWriteValueOptions<OPTIONS, true>> | undefined
> {
  const {
    mode = 'put',
    fill = true,
    transform = true,
    defined = false,
    /**
     * @debt type "Maybe there's a way not to have to cast here"
     */
    parseExtension = defaultParseExtension as unknown as NonNullable<OPTIONS['parseExtension']>,
    valuePath
  } = options

  let filledValue = inputValue
  let nextFill = fill

  if (nextFill && filledValue === undefined) {
    let defaultedValue = undefined

    const modeDefault = getDefaulter(schema, mode)
    defaultedValue = isFunction(modeDefault) ? modeDefault() : (cloneDeep(modeDefault) as any)

    const itemInput = yield defaultedValue

    let linkedValue = defaultedValue
    if (linkedValue === undefined && itemInput !== undefined) {
      const modeLink = getModeLink(schema, mode)
      linkedValue = (isFunction(modeLink) ? modeLink(itemInput) : linkedValue) as any
    }
    yield linkedValue

    filledValue = linkedValue
    nextFill = false
  }

  const nextOpts = { ...options, fill: nextFill } as OPTIONS

  const { isExtension, extensionParser, unextendedInput } = parseExtension(schema, filledValue, {
    transform,
    valuePath
  })

  if (isExtension) {
    if (nextFill) {
      // parseExtension does not fill values
      // If fill was set to `true` and input was defined, we yield it twice for fill steps
      const defaultedValue = filledValue
      yield defaultedValue

      const linkedValue = defaultedValue
      yield linkedValue
    }
    return yield* extensionParser()
  }

  if (unextendedInput === undefined) {
    const path = valuePath !== undefined ? formatArrayPath(valuePath) : undefined

    // We don't need to fill
    if (isRequired(schema, mode) || defined) {
      throw new DynamoDBToolboxError('parsing.attributeRequired', {
        message: `Attribute${path !== undefined ? ` '${path}'` : ''} is required.`,
        path
      })
    }

    const parsedValue = unextendedInput

    if (transform) {
      yield parsedValue
    } else {
      return parsedValue
    }

    const transformedValue = parsedValue
    return transformedValue
  }

  switch (schema.type) {
    case 'any':
      return yield* anySchemaParser(schema, unextendedInput, nextOpts)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return yield* primitiveSchemaParser(schema, unextendedInput, nextOpts)
    case 'set':
      return yield* setSchemaParser(schema, unextendedInput, nextOpts)
    case 'list':
      return yield* listSchemaParser(schema, unextendedInput, nextOpts)
    case 'map':
      return yield* mapSchemaParser(schema, unextendedInput, nextOpts)
    case 'record':
      return yield* recordSchemaParser(schema, unextendedInput, nextOpts)
    case 'anyOf':
      return yield* anyOfSchemaParser(schema, unextendedInput, nextOpts)
  }
}

const getDefaulter = (schema: Schema, mode: WriteMode) => {
  const { props } = schema

  if (props.key) {
    return props.keyDefault
  }

  switch (mode) {
    case 'key':
      return props.keyDefault
    case 'put':
      return props.putDefault
    case 'update':
      return props.updateDefault
  }
}

const getModeLink = (schema: Schema, mode: WriteMode) => {
  const { props } = schema

  if (props.key) {
    return props.keyLink
  }

  switch (mode) {
    case 'key':
      return props.keyLink
    case 'put':
      return props.putLink
    case 'update':
      return props.updateLink
  }
}
export { Parser } from './parser.js'
export type { ParseValueOptions, InferWriteValueOptions } from './options.js'
import { DynamoDBToolboxError } from '~/errors/index.js'
import type {
  InputValue,
  Schema,
  TransformedValue,
  ValidValue,
  WriteValueOptions
} from '~/schema/index.js'
import { SchemaAction } from '~/schema/index.js'

import { itemParser } from './item.js'
import type { InferWriteValueOptions, ParseValueOptions } from './options.js'
import { schemaParser } from './schema.js'

type ParserInput<
  SCHEMA extends Schema,
  OPTIONS extends ParseValueOptions = {},
  WRITE_VALUE_OPTIONS extends WriteValueOptions = InferWriteValueOptions<OPTIONS>
> = OPTIONS extends { fill: false }
  ? ValidValue<SCHEMA, WRITE_VALUE_OPTIONS>
  : InputValue<SCHEMA, WRITE_VALUE_OPTIONS>

export type ParserYield<
  SCHEMA extends Schema,
  OPTIONS extends ParseValueOptions = {},
  WRITE_VALUE_OPTIONS extends WriteValueOptions = InferWriteValueOptions<OPTIONS>
> =
  | (OPTIONS extends { fill: false } ? never : InputValue<SCHEMA, WRITE_VALUE_OPTIONS>)
  | ValidValue<SCHEMA, WRITE_VALUE_OPTIONS>

export type ParserReturn<
  SCHEMA extends Schema,
  OPTIONS extends ParseValueOptions = {},
  WRITE_VALUE_OPTIONS extends WriteValueOptions = InferWriteValueOptions<OPTIONS>
> = OPTIONS extends { transform: false }
  ? ValidValue<SCHEMA, WRITE_VALUE_OPTIONS>
  : TransformedValue<SCHEMA, WRITE_VALUE_OPTIONS>

export class Parser<SCHEMA extends Schema> extends SchemaAction<SCHEMA> {
  static override actionName = 'parse' as const

  start<OPTIONS extends ParseValueOptions = {}>(
    inputValue: unknown,
    options: OPTIONS = {} as OPTIONS
  ): Generator<ParserYield<SCHEMA, OPTIONS>, ParserReturn<SCHEMA, OPTIONS>> {
    if (this.schema.type === 'item') {
      return itemParser(this.schema, inputValue, options) as Generator<
        ParserYield<SCHEMA, OPTIONS>,
        ParserReturn<SCHEMA, OPTIONS>
      >
    } else {
      return schemaParser(this.schema, inputValue, options) as Generator<
        ParserYield<SCHEMA, OPTIONS>,
        ParserReturn<SCHEMA, OPTIONS>
      >
    }
  }

  parse<OPTIONS extends ParseValueOptions = {}>(
    inputValue: unknown,
    options: OPTIONS = {} as OPTIONS
  ): ParserReturn<SCHEMA, OPTIONS> {
    const parser = this.start(inputValue, options)

    let done = false
    let value: ParserReturn<SCHEMA, OPTIONS>
    do {
      const nextProps = parser.next()
      done = Boolean(nextProps.done)
      // TODO: Not cast
      value = nextProps.value as ParserReturn<SCHEMA, OPTIONS>
    } while (!done)

    return value
  }

  reparse<OPTIONS extends ParseValueOptions = {}>(
    inputValue: ParserInput<SCHEMA, OPTIONS>,
    options: OPTIONS = {} as OPTIONS
  ): ParserReturn<SCHEMA, OPTIONS> {
    return this.parse(inputValue, options)
  }

  validate<OPTIONS extends Omit<ParseValueOptions, 'fill' | 'transform'> = {}>(
    inputValue: unknown,
    options: OPTIONS = {} as OPTIONS
  ): inputValue is ValidValue<SCHEMA, OPTIONS> {
    try {
      this.parse(inputValue, { ...options, fill: false, transform: false })
    } catch (error) {
      if (error instanceof DynamoDBToolboxError && DynamoDBToolboxError.match(error, 'parsing.')) {
        return false
      }

      throw error
    }

    return true
  }
}

export { getSchemaDTO } from './schema.js'
import type { Schema } from '~/schema/index.js'

import type { ISchemaDTO } from '../types.js'
import { getAnySchemaDTO } from './any.js'
import { getAnyOfSchemaDTO } from './anyOf.js'
import { getItemSchemaDTO } from './item.js'
import { getListSchemaDTO } from './list.js'
import { getMapSchemaDTO } from './map.js'
import { getPrimitiveSchemaDTO } from './primitive.js'
import { getRecordSchemaDTO } from './record.js'
import { getSetSchemaDTO } from './set.js'

export const getSchemaDTO = (schema: Schema): ISchemaDTO => {
  /**
   * @debt feature "handle defaults, links & validators"
   */
  switch (schema.type) {
    case 'any':
      return getAnySchemaDTO(schema)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return getPrimitiveSchemaDTO(schema)
    case 'set':
      return getSetSchemaDTO(schema)
    case 'list':
      return getListSchemaDTO(schema)
    case 'map':
      return getMapSchemaDTO(schema)
    case 'record':
      return getRecordSchemaDTO(schema)
    case 'anyOf':
      return getAnyOfSchemaDTO(schema)
    case 'item':
      return getItemSchemaDTO(schema)
  }
}
import type { AnySchema } from '~/schema/any/index.js'
import { isSerializableTransformer } from '~/transformers/index.js'

import type { AnySchemaDTO, AnySchemaTransformerDTO } from '../types.js'
import { getDefaultsDTO } from './utils.js'

/**
 * @debt feature "handle defaults, links & validators DTOs"
