import type { LazySchema } from '~/schema/index.js'

import type { ISchemaDTO } from '../types.js'
import type { GetSchemaDTOContext } from './context.js'
import { getSchemaDTO } from './schema.js'

export const getLazySchemaDTO = (schema: LazySchema, context: GetSchemaDTOContext): ISchemaDTO => {
  const existingRef = context.refs.get(schema)
  if (existingRef !== undefined) {
    return { $ref: existingRef }
  }

  const ref = `lazy-${context.counter}`
  context.counter += 1

  context.refs.set(schema, ref)

  const def = getSchemaDTO(schema.resolve(), context)
  context.defs.set(ref, def)

  return { $ref: ref }
}
